  ('ai:ai-batch-03:a8d0be70f837','A1'::public.cefr_level,'reading','What is the capital city of the United Kingdom?',array['London','Cardiff','Erbil','Paris']::text[],'A','''London is the capital city of England and of the United Kingdom.''',array['life_in_uk','story']::text[],'draft','unreviewed','ai-draft:ai-batch-03','Sam lives in London. London is the capital city of England and of the United Kingdom. The River Thames goes through London. Every day Sam walks to school. He likes the red buses. On Saturdays he visits his grandmother in Cardiff, the capital city of Wales.',null,null,null),
  ('ai:ai-batch-03:7e164ffead13','A1'::public.cefr_level,'reading','Which river goes through London?',array['the Thames','the Nile','the Severn','the Tigris']::text[],'A','''The River Thames goes through London.''',array['life_in_uk','story']::text[],'draft','unreviewed','ai-draft:ai-batch-03','Sam lives in London. London is the capital city of England and of the United Kingdom. The River Thames goes through London. Every day Sam walks to school. He likes the red buses. On Saturdays he visits his grandmother in Cardiff, the capital city of Wales.',null,null,null),
  ('ai:ai-batch-03:028453bb741d','A1'::public.cefr_level,'reading','Where does Sam''s grandmother live?',array['in Cardiff','in Edinburgh','in Erbil','in London']::text[],'A','''He visits his grandmother in Cardiff.''',array['life_in_uk','story']::text[],'draft','unreviewed','ai-draft:ai-batch-03','Sam lives in London. London is the capital city of England and of the United Kingdom. The River Thames goes through London. Every day Sam walks to school. He likes the red buses. On Saturdays he visits his grandmother in Cardiff, the capital city of Wales.',null,null,null),
  ('ai:ai-batch-03:7e813277837c','A1'::public.cefr_level,'reading','What is in the centre of Erbil?',array['an airport','an old citadel','a beach','a big lake']::text[],'B','''In the centre of the city there is a very old citadel.''',array['kurdistan','story']::text[],'draft','unreviewed','ai-draft:ai-batch-03','My name is Hana. I live in Erbil. Erbil is the capital city of the Kurdistan Region. In the centre of the city there is a very old citadel on a hill. In March we celebrate Newroz. We go to the mountains and have a picnic with our family.',null,null,null),
