  ('ai:ai-batch-03:27f2e619da4f','A1'::public.cefr_level,'vocabulary','Watch the video. What is the date of Newroz?',array['1 January','21 June','21 March','12 March']::text[],'C','The video shows ''Newroz, 21 March''.',array['kurdistan']::text[],'draft','unreviewed','ai-draft:ai-batch-03',null,'video','samples/newroz.mp4','Newroz (7 seconds)'),
  ('ai:ai-batch-03:82d9305db596','A2'::public.cefr_level,'reading','When is Newroz celebrated?',array['on 1 January','on 31 December','on 21 June','on 21 March']::text[],'D','''It is celebrated on 21 March, at the start of spring.''',array['kurdistan','story']::text[],'draft','unreviewed','ai-draft:ai-batch-03','Newroz is the Kurdish New Year. It is celebrated on 21 March, at the start of spring. The story of Newroz tells of Kawa the blacksmith, who fought against a cruel king called Zuhak. After Kawa won, people lit fires on the hills to share the good news. Today people still light fires, wear traditional clothes and dance together.',null,null,null),
  ('ai:ai-batch-03:400cae6c0030','A2'::public.cefr_level,'reading','In the Newroz story, who was Kawa?',array['a king','a blacksmith','a farmer','a teacher']::text[],'B','''Kawa the blacksmith''.',array['kurdistan','story']::text[],'draft','unreviewed','ai-draft:ai-batch-03','Newroz is the Kurdish New Year. It is celebrated on 21 March, at the start of spring. The story of Newroz tells of Kawa the blacksmith, who fought against a cruel king called Zuhak. After Kawa won, people lit fires on the hills to share the good news. Today people still light fires, wear traditional clothes and dance together.',null,null,null),
  ('ai:ai-batch-03:7a42dd046e79','A2'::public.cefr_level,'reading','Why did people light fires on the hills?',array['to frighten animals','to keep warm','to cook food','to share the good news']::text[],'D','''People lit fires on the hills to share the good news.''',array['kurdistan','story']::text[],'draft','unreviewed','ai-draft:ai-batch-03','Newroz is the Kurdish New Year. It is celebrated on 21 March, at the start of spring. The story of Newroz tells of Kawa the blacksmith, who fought against a cruel king called Zuhak. After Kawa won, people lit fires on the hills to share the good news. Today people still light fires, wear traditional clothes and dance together.',null,null,null),
  ('ai:ai-batch-03:1cc0a8c1d983','A2'::public.cefr_level,'reading','How many countries make up the United Kingdom?',array['two','five','four','three']::text[],'C','England, Scotland, Wales and Northern Ireland.',array['life_in_uk','story']::text[],'draft','unreviewed','ai-draft:ai-batch-03','The United Kingdom is made up of four countries: England, Scotland, Wales and Northern Ireland. Their capital cities are London, Edinburgh, Cardiff and Belfast. ''Great Britain'' is the name for England, Scotland and Wales together. Northern Ireland is on the island of Ireland.',null,null,null),
  ('ai:ai-batch-03:37b32da9d6d5','A2'::public.cefr_level,'reading','What is the capital city of Scotland?',array['Belfast','Glasgow','Cardiff','Edinburgh']::text[],'D','The capitals are London, Edinburgh, Cardiff and Belfast.',array['life_in_uk','story']::text[],'draft','unreviewed','ai-draft:ai-batch-03','The United Kingdom is made up of four countries: England, Scotland, Wales and Northern Ireland. Their capital cities are London, Edinburgh, Cardiff and Belfast. ''Great Britain'' is the name for England, Scotland and Wales together. Northern Ireland is on the island of Ireland.',null,null,null),
  ('ai:ai-batch-03:83bc8c12b8db','A2'::public.cefr_level,'reading','Which country is NOT part of Great Britain?',array['Scotland','England','Wales','Northern Ireland']::text[],'D','Great Britain = England, Scotland and Wales.',array['life_in_uk','story']::text[],'draft','unreviewed','ai-draft:ai-batch-03','The United Kingdom is made up of four countries: England, Scotland, Wales and Northern Ireland. Their capital cities are London, Edinburgh, Cardiff and Belfast. ''Great Britain'' is the name for England, Scotland and Wales together. Northern Ireland is on the island of Ireland.',null,null,null),
  ('ai:ai-batch-03:6ae3f98769ec','A2'::public.cefr_level,'reading','Why is Lana phoning the health centre?',array['to cancel an appointment','to register at a school','to buy medicine','to make an appointment with a doctor']::text[],'D','''I''d like to make an appointment with a doctor.''',array['dialogue','life_in_uk']::text[],'draft','unreviewed','ai-draft:ai-batch-03','Receptionist: Good morning, City Health Centre.
